import re

def parse(lines):
    rec = {}
    used = []
    skip = []
    sec = ''
    for i, l in enumerate(lines):
        if not l.strip():
            continue
        if not l[:1].isspace() and ':' not in l:
            sec = l.strip()
            skip.append(i)
            continue
        m = re.match(r'^\s*(?P<who>\S.*?)\s*\((?P<f>[a-z ]+)\):\s*(?P<v>.*\S)\s*$', l)
        if m:
            fs = m.group('f').split()
            vs = m.group('v').split()
            for f, v in zip(fs, vs):
                rec[(sec + ' ' + m.group('who') + ' ' + f).strip()] = v
            used.append(i)
            continue
        ok = False
        for seg in re.split(r'\t+', l):
            mm = re.match(r'^\s*(?P<k>[^:]+?):\s*(?P<v>.*?)\s*$', seg)
            if mm:
                rec[mm.group('k')] = mm.group('v')
                ok = True
        if ok:
            used.append(i)
    blocks = []
    if rec:
        blocks.append({'name': 'process', 'kind': 'kv', 'lines': used, 'records': [rec]})
    return {'blocks': blocks, 'skip': skip}
